#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif
/* machine-generated by m2c: a starting point, not a match */

extern char gItemTableBytes[];

/* Returns a byte from the 12-byte-stride item table entry for index, clamped to 0..0x78. */ u8 getItemTableByte(s32 index) {
    s32 clampedIndex;

    clampedIndex = index & -(index < 0x7A);
    if (clampedIndex < 0) {
        clampedIndex = 0x78;
    }
    return *(gItemTableBytes + (clampedIndex * 0xC));
}
